"""Create an auditable event crosswalk; no PMU access and no raw-register CLI."""
import hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent
if len(sys.argv)==3:
 apple_path,intel_path=map(Path,sys.argv[1:]);apple=json.loads(apple_path.read_text())['system']['cpu']['events'];intel={r['EventName']:r for r in json.loads(intel_path.read_text())['Events']}
 names=['IDQ.DSB_UOPS','IDQ.MITE_UOPS','IDQ.MS_UOPS','DSB2MITE_SWITCHES.PENALTY_CYCLES','BR_MISP_RETIRED.ALL_BRANCHES','BACLEARS.ANY','MACHINE_CLEARS.COUNT','MACHINE_CLEARS.MEMORY_ORDERING','MACHINE_CLEARS.SMC','LD_BLOCKS.STORE_FORWARD','LD_BLOCKS_PARTIAL.ADDRESS_ALIAS','UOPS_ISSUED.ANY','UOPS_RETIRED.RETIRE_SLOTS','ICACHE_64B.IFTAG_MISS','CYCLE_ACTIVITY.STALLS_TOTAL','RESOURCE_STALLS.ANY','LSD.UOPS']
 names+=sorted(n for n in apple if n.startswith(('FRONTEND_RETIRED.','ITLB_MISSES.')))
 rows=[]
 for name in names:
  local=apple.get(name);official=intel.get(name);row={'name':name,'apple':local and {k:v for k,v in local.items() if k!='description'},'intel':official and {k:official[k] for k in ('EventCode','UMask','CounterMask','EdgeDetect','Invert','AnyThread','MSRIndex','MSRValue','PEBS','TakenAlone','Counter')}}
  reason='available'
  if not local:reason='absent from local kpep database; no silent alias or fabricated encoding'
  elif not official:reason='absent from pinned Intel SKL crosswalk'
  elif int(official['MSRIndex'],0) or official['TakenAlone']!='0':reason='requires auxiliary MSR/PEBS selector not exposed by this tool; names alone insufficient'
  elif int(official['EventCode'],0)!=local.get('number') or int(official['UMask'],0)!=local.get('umask'):reason='local EventCode/UMask disagrees with Intel'
  row.update(supported=reason=='available',reason=reason);rows.append(row)
 data={'diagnostic_only':True,'cpu':'GenuineIntel family6/modelA5/step5','intel_url':'https://raw.githubusercontent.com/intel/perfmon/main/SKL/events/skylake_core.json','intel_sha256':hashlib.sha256(intel_path.read_bytes()).hexdigest(),'apple_catalog_sha256':hashlib.sha256(apple_path.read_bytes()).hexdigest(),'fixed_counters':{'instructions':{'index':0,'fixed_control_user_bit':1},'cycles':{'index':1,'fixed_control_user_bit':5}},'events':rows}
 (ROOT/'event-inventory.json').write_text(json.dumps(data,indent=2)+'\n')
else:data=json.loads((ROOT/'event-inventory.json').read_text())
s='/* Generated by inventory.py from sealed event-inventory.json. Named CPU policy, no user register input. */\n'
s+='typedef struct {const char *name;unsigned number,umask,cmask,edge,invert;} Approved;\nstatic const Approved approved[]={\n'
for r in data['events']:
 if r['supported']:
  i=r['intel'];s+=' {"'+r['name']+'",'+','.join(str(int(i[k],0)) for k in ('EventCode','UMask','CounterMask','EdgeDetect','Invert'))+'},\n'
s+='};\n';(ROOT/'events-approved.h').write_text(s)
print('supported',sum(r['supported'] for r in data['events']),'unavailable',sum(not r['supported'] for r in data['events']))
